import{z as r,x as s,o as t,c as d,q as n,j as o,D as A,d as E,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"教育生产函数的深化","description":"","frontmatter":{"title":"教育生产函数的深化","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ed2-production-deep.md","filePath":"econ/ed2-production-deep.md","lastUpdated":1791413859000}'),p={name:"econ/ed2-production-deep.md"};function c(u,a,D,h,m,F){const B=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="教育生产函数的深化" tabindex="-1">教育生产函数的深化 <a class="header-anchor" href="#教育生产函数的深化" aria-label="Permalink to &quot;教育生产函数的深化&quot;">​</a></h1><div class="epigraph"><p>生产函数写下可以购买的投入，产出却大部分不来自它们——教育的账本上，最值钱的一栏填不进价格。</p><footer>—— 据 Coleman, Equality of Educational Opportunity, 1966；Hanushek, Economic Journal 2003 整理</footer></div><p><a href="/econ/env-map">上一课</a>把环境经济学收成一张地图：全部工具是「楔在哪、楔多深、谁付钱」的三元组，可信度靠规则化维持，共有边界是临界点、无世界政府与跨代贴现。主干课的<a href="/econ/human-capital-becker">人力资本</a>把教育与培训写成可积累的资本：投资前密后疏，租期效应压出凹形的年龄–收入剖面——但那条剖面把学校当黑箱，同一年书，在不同的教室里买到的并不是同一种资本。本课是「教育经济学」的第一课，任务是打开黑箱：学校这份按年计的资本由哪些投入生产、产出该怎么记账、钱花在哪里边际上真的有效。后课的教师激励、学校选择、高等教育与技能形成，都默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把教育写成生产函数：\\(Y = f(F, S, P)\\)，产出 \\(Y\\) 是学业成绩，投入是家庭 \\(F\\)、学校 \\(S\\) 与同伴 \\(P\\)。Coleman 1966 年的报告给出了第一版令人不安的读数：家庭与同伴的解释力远大于学校的可观测投入——图书馆、生均经费、实验室在方程里几乎站不住。麻烦不在「学校无用」这个标题，而在三个更深的技术缺口：产出只记分数不记长期结果；投入是流量而学习是存量，静态回归把两者搅在一起；投入还有质量维度——同样一笔经费，买到的人和物可以完全不同。<a href="/econ/ca-education-causal">教育中的因果问题</a>已经把识别问题交给了准实验，本课补的是另一半：函数本身该怎么写，写错了会把政策引向哪里。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>动态口径从存量记账开始：把上一期的成绩当作本期生产的投入之一，</p> \\[A_{it} = \\alpha A_{i,t-1} + \\beta q_{it} + \\gamma F_i + \\varepsilon_{it}, \\]<p>其中 \\(q_{it}\\) 是当年课堂质量的投入，\\(\\alpha\\) 度量知识的留存。<span class="marginnote">数字实例：设 \\(\\alpha=0.8\\)——今年学的东西明年留存八成。去年存量 100、今年课堂贡献 20，今年存量就是 \\(0.8\\times100+20=100\\)；若 \\(\\alpha=0.5\\)，同样投入只到 70。留存率不同，同样花钱攒出的复利完全不同。</span>这个「增值」设定（Todd–Wolpin 2003 的口径）把家庭与早期教育的积累折叠进 \\(A_{i,t-1}\\)，于是 \\(\\beta\\) 读的是当年学校这一段的边际贡献，而不是累计教育水平的总效应——两者在政策上完全是两个问题。<span class="marginnote">术语翻译：「增值」就是不比水平比进步——不看期末考了多少分，看这一年从开学到学期末长进了多少。起点差异（家庭、学前教育）被折进「上一期成绩」里，剩下的才是学校这一段自己挣出来的部分。</span>产出端同样要记账：分数是代理变量，收入才是产出；代理会衰减而效应不一定衰减，这是后面每一课都要用到的口径。</p>',9)),(t(),o(l,null,{default:A(()=>[i(B,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%AE%B6%E5%BA%AD%E6%8A%95%E5%85%A5%20F%22%5D%20--%3E%20A%5B%22%E7%B4%AF%E7%A7%AF%E5%AD%A6%E4%B8%9A%E5%AD%98%E9%87%8F%22%5D%0A%20%20P%5B%22%E5%90%8C%E4%BC%B4%E6%9E%84%E6%88%90%20P%22%5D%20--%3E%20A%0A%20%20S%5B%22%E5%AD%A6%E6%A0%A1%E5%8F%AF%E8%A7%82%E6%B5%8B%E6%8A%95%E5%85%A5%EF%BC%9A%E7%BB%8F%E8%B4%B9%E3%80%81%E7%8F%AD%E7%BA%A7%E8%A7%84%E6%A8%A1%22%5D%20--%3E%20Q%5B%22%E8%AF%BE%E5%A0%82%E8%B4%A8%E9%87%8F%20q%EF%BC%9A%E4%B8%8D%E5%8F%AF%E8%A7%82%E6%B5%8B%22%5D%0A%20%20Q%20--%3E%20A%0A%20%20A%20--%3E%20B%5B%22%E5%BD%93%E5%B9%B4%E5%A2%9E%E5%80%BC%20%CE%B2q%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%B5%8B%E9%AA%8C%E5%88%86%E6%95%B0%EF%BC%9A%E4%BB%A3%E7%90%86%EF%BC%8C%E4%BC%9A%E8%A1%B0%E5%87%8F%22%5D%0A%20%20B%20--%3E%20D%5B%22%E9%95%BF%E6%9C%9F%E6%94%B6%E5%85%A5%EF%BC%9A%E4%BA%A7%E5%87%BA%EF%BC%8C%E4%B8%8D%E8%A1%B0%E5%87%8F%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("为什么「买投入买不来质量」？Rivkin–Hanushek–Kain 2005 用德州全州面板给出了分解：教师之间的产出差大得足以重排一所学校的均值，但教龄、学历、证书这些可观测特征几乎解释不了这个差——薪级表定价的那几栏，恰好不是产出所在的那栏。"),e("span",{class:"marginnote"},"直觉类比：像评估厨师却只看工龄和证书——厨房里真正的差距在火候与调味，而这两样不写在简历上。薪级表按简历定价，产出却按火候结算，错位由此而来。"),E("Hanushek 对数百项研究的元统计长期指向同一结论：师生比等资源投入的估计里，显著为正的比例停留在四分之一上下，与随机没差多少。这不是「投入都无效」，而是"),e("strong",null,"平均口径"),E("的无效：钱不挑人地铺下去，大部分落在本就有效的存量上。少数确凿的例外都在边际上——"),e("a",{href:"/econ/ca-education-causal"},"教育中的因果问题"),E("里的 Project STAR 把班级规模砍到 13–17 人，早期分数抬高约 0.15–0.25 个标准差；而小班的分数红利几年内消退、成年收入红利却不消退（Chetty 等 2011），说明衰减的是代理，不是效应。")],-1)),a[5]||(a[5]=e("p",null,"平均口径为什么读出零、边际口径却读得出效果，取决于钱落在分布哪一段。",-1)),(t(),o(l,null,{default:A(()=>[i(B,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E4%B8%80%E7%AC%94%E4%B8%8D%E6%8C%91%E4%BA%BA%E7%9A%84%E5%B9%B3%E5%9D%87%E6%8A%95%E5%85%A5%22%5D%20--%3E%20D%7B%22%E8%90%BD%E5%9C%A8%E5%AD%98%E9%87%8F%E5%88%86%E5%B8%83%E5%93%AA%E4%B8%80%E6%AE%B5%22%7D%0A%20%20D%20--%3E%7C%22%E5%AD%98%E9%87%8F%E5%B7%B2%E9%AB%98%2C%20%E6%8A%95%E5%85%A5%E5%86%97%E4%BD%99%22%7C%20W%5B%22%E5%A4%A7%E5%A4%9A%E6%95%B0%E5%AD%A6%E7%94%9F%3A%20%E6%95%88%E5%BA%94%E6%8E%A5%E8%BF%91%E9%9B%B6%22%5D%0A%20%20D%20--%3E%7C%22%E5%AD%98%E9%87%8F%E8%A2%AB%E7%BA%A6%E6%9D%9F%22%7C%20E%5B%22%E5%B0%91%E6%95%B0%E8%BE%B9%E9%99%85%E5%AD%A6%E7%94%9F%3A%20%E6%95%88%E5%BA%94%E5%8F%AF%E8%A7%82%22%5D%0A%20%20W%20--%3E%20SUM%5B%22%E5%8A%A0%E6%80%BB%E8%AF%BB%E6%95%B0%3A%20%E5%B9%B3%E5%9D%87%E6%95%88%E5%BA%94%E8%BF%91%E9%9B%B6%22%5D%0A%20%20E%20--%3E%20SUM%0A%20%20SUM%20--%3E%20LESSON%5B%22%E9%A2%84%E7%AE%97%E5%8F%A3%E5%BE%84%3A%20%E9%93%BA%E5%B9%B3%E5%9D%87%E4%B8%8D%E5%A6%82%E6%89%BE%E8%BE%B9%E9%99%85%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">Hanushek 2003 的元统计：数百项研究中，资源类投入（师生比、生均经费、教师学历）显著为正的比例长期在四分之一上下，显著为负的也有约一成——「投入平均无效」是有完整分布支撑的结论，不是一句口号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>第一，增值模型不是无懈可击的识别：学生与教师非随机匹配，\\(\\beta\\) 里混着分拣，干净的读数要靠随机分班的子样本来校准——本课只钉函数形式，识别口径见因果问题那课。第二，「平均无效」不构成「钱无用」的证明：生产函数说的是平均投入的零效应，下一课会看到被约束的边际（教师的进入与退出）上，钱依然有效。第三，本课的函数是削减式近似，不含治理与激励结构——学校不是一台接受投入就吐出成绩的机器，怎么让教师想教好、让学校想变好，是接下来两课的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>教育生产函数要按存量记账：\\(A_{it} = \\alpha A_{i,t-1} + \\beta q_{it} + \\gamma F_i + \\varepsilon_{it}\\)，\\(\\beta\\) 是当年课堂投入的边际效应。</li><li>产出有两本账：分数是会衰减的代理，收入才是产出；两者可以背离。</li><li>教师效应大而不可观测特征解释不了它——薪级表定价的维度不是产出的维度。</li><li>资源投入平均效应近零（Hanushek 元统计），边际投入可以很大（STAR）。</li><li>出处：Coleman 1966；Todd and Wolpin, JEL 2003；Rivkin, Hanushek and Kain, Econometrica 2005；Hanushek, Economic Journal 2003；Chetty 等, QJE 2011。</li></ul>',5))])}const f=r(p,[["render",c]]);export{C as __pageData,f as default};
